from speech_models import SynthesisRequest, SynthesisResponse

def synthesize_ssml(payload, config=None) -> SynthesisResponse:
    config = config or {}
    client = TextToSpeechClient()
    request = SynthesisRequest(
        ssml=payload["ssml"],
        language_code=config.get("language_code", "en-US"),
        voice_name=config.get("voice_name"),
        audio_encoding=config.get("audio_encoding", "MP3")
    )
    return client.synthesize(request)

from speech_client import TextToSpeechClient
from speech_models import Voice, VoiceSelection

def select_voice(payload, config=None) -> list[Voice]:
    config = config or {}
    client = TextToSpeechClient()
    language_code = payload.get("language_code", config.get("language_code"))
    voices = client.list_voices(language_code=language_code)

    # Further filtering based on payload if needed (e.g., gender, specific name)
    filtered_voices = []
    for voice in voices:
        if "gender" in payload and voice.gender != payload["gender"].upper():
            continue
        if "name" in payload and voice.name != payload["name"]:
            continue
        filtered_voices.append(voice)

    return filtered_voices

from speech_models import SynthesisResponse

def save_audio(audio_data: SynthesisResponse, file_path: str):
    # The audio_data.audio_bytes comes directly from Google Cloud Text-to-Speech API
    # No further provider-specific processing needed here, just writing the bytes.
    try:
        with open(file_path, "wb") as f:
            f.write(audio_data.audio_bytes)
        return {"status": "success", "file_path": file_path, "content_type": audio_data.content_type}
    except Exception as e:
        return {"status": "error", "message": str(e)}

from google.cloud import translate_v2 as translate

def script_translate(payload, config=None):
    config = config or {}
    translate_client = translate.Client()
    text = payload["text"]
    target_language = config.get("target_language", "es")

    response = translate_client.translate(
        text,
        target_language=target_language
    )

    return {"translated_text": response["translatedText"], "source_language": response["detectedSourceLanguage"]}
